SELECT n.entity_kind || ' ' || coalesce(nullif(n.entity_name, ''), '(одиночный)') || ' → ' || n.said_id || ': имени нет в наборе' AS detail FROM project_named_id n WHERE n.project_id = $1 AND NOT n.caveated AND NOT n.from_range AND NOT EXISTS (SELECT 1 FROM project_requirements r WHERE r.project_id = n.project_id AND r.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_checks c WHERE c.project_id = n.project_id AND c.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_stories s WHERE s.project_id = n.project_id AND s.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_screens sc WHERE sc.project_id = n.project_id AND sc.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_needs nd WHERE nd.project_id = n.project_id AND nd.id = n.said_id) AND NOT EXISTS (SELECT 1 FROM project_named_id t JOIN project_plan_tasks p ON p.project_id = t.project_id AND p.id = t.entity_name WHERE t.project_id = n.project_id AND t.entity_kind = 'task' AND t.said_id = n.said_id AND p.state <> 'closed') AND true ORDER BY 1
